def _seed_consent_templates() -> None:
    import uuid

    table = sa.table(
        "consent_templates",
        sa.column("id", sa.Uuid()),
        sa.column("type", sa.String()),
        sa.column("version", sa.Integer()),
        sa.column("title", sa.String()),
        sa.column("body", sa.Text()),
        sa.column("is_active", sa.Boolean()),
    )
    op.bulk_insert(
        table,
        [
            {
                "id": uuid.uuid4(),
                "type": kind,
                "version": 1,
                "title": title,
                "body": _EXAMPLE_NOTICE + body,
                "is_active": True,
            }
            for kind, title, body in _CONSENT_TEMPLATES
        ],
    )


def _seed_icd10() -> None:
    table = sa.table(
        "icd10_codes", sa.column("code", sa.String()), sa.column("description", sa.String())
    )
    op.bulk_insert(table, [{"code": code, "description": text} for code, text in _ICD10_SAMPLE])
